head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst00400";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst00400.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#ipt_etfIsuSrtNm").bind("change", function() {
                $c.util.getComponent('ipt_etfIsuSrtCd').setValue("");
        });
        $("#ipt_reportNm").bind("change", function() {
                $c.util.getComponent('ipt_reportCd').setValue("");
        });
        $("#ipt_etfIsuSrtNm").bind("keypress", async function(e) {
                if (e.keyCode === 13) {
                    if ($c.util.getComponent('ipt_etfIsuSrtNm').getValue() !== $c.util.getComponent('ipt_etfIsuSrtCd').getValue()) {
                        $c.util.getComponent('ipt_etfIsuSrtCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        $("#ipt_reportNm").bind("keypress", async function(e) {
                if (e.keyCode === 13) {
                    if ($c.util.getComponent('ipt_reportNm').getValue() !== $c.util.getComponent('ipt_reportTmp').getValue()) {
                        $c.util.getComponent('ipt_reportCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod( "1 ') */
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00400.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

