 */
scwin.btn_pd_1w_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addDate(to, -7); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst00400.pd_1w' }); } };

